/* eslint-disable @typescript-eslint/no-explicit-any */
// Soft-delete inherently routes runtime args through dynamic Prisma delegates and
// rebuilds where-clauses that don't fit the strict per-operation arg unions
// generated by Prisma. We isolate the `any` usage to this file and keep the
// extension's types accurate at the consumer boundary (`SoftDeletedPrismaClient`).

import { Prisma, type PrismaClient } from '@prisma/client';

const SOFT_DELETE_MODELS = new Set<string>([
  'User',
  // Organization rows can be archived (soft-deleted) as the reversible
  // half of the dual-delete contract. Including it here makes every
  // ordinary org query auto-filter `deletedAt: null`; the admin-restore
  // path must pass `{ includeDeleted: true }` to see archived rows.
  'Organization',
  'Workspace',
  'Project',
  'Task',
  'Lead',
  'Client',
  'Document',
  'FileObject',
  'Comment',
  // Financials. `Invoice` has always had a `deletedAt` column but was never
  // listed here, so `invoice.delete()` was a HARD delete - money records
  // vanished irrecoverably. Listing it fixes that.
  //
  // Deliberately ABSENT: `Payment` (voided via `voidedAt`, never deleted, so
  // the audit trail stays visible) and `ContractMilestone` (cascades from its
  // Contract, which is the right granularity).
  'Contract',
  'Expense',
  'Invoice',
  // E-signature requests are cancelled rather than deleted in the UI; a
  // delete still keeps the audit trail recoverable.
  'SignatureRequest',
  // Client-portal access. Revoking soft-deletes the row, so a re-invite must
  // `upsert` on (clientId, userId) with `deletedAt: null` - `findUnique` no
  // longer sees the revoked row and a plain `create` hits the unique key.
  'ClientContact',
  'Role',
  // Payroll. Re-adding a removed person upserts on (workspaceId, userId) with
  // `deletedAt: null` (someone without a platform account has no userId and
  // is simply created again); a discarded DRAFT run is hard-deleted when a new run
  // for the same month is created. PayrollItem cascades from its run.
  'PayrollEmployee',
  'PayrollRun',
]);

const isSoftDeleteModel = (model: string | undefined): boolean =>
  !!model && SOFT_DELETE_MODELS.has(model);

const lcfirst = (s: string): string => s.charAt(0).toLowerCase() + s.slice(1);

interface PartitionResult {
  rest: any;
  includeDeleted: boolean;
}

function partition(args: any): PartitionResult {
  if (args && args.includeDeleted === true) {
    const { includeDeleted: _ignored, ...rest } = args;
    return { rest, includeDeleted: true };
  }
  return { rest: args, includeDeleted: false };
}

function withDeletedAtNull(args: any): any {
  return { ...(args ?? {}), where: { ...(args?.where ?? {}), deletedAt: null } };
}

/** One soft-delete that just happened: the model and how many rows it hit. */
export interface SoftDeleteEvent {
  model: string;
  count: number;
}

let softDeleteListener: ((event: SoftDeleteEvent) => void) | null = null;

/**
 * Register a single observer for soft-deletes (the API's security alerts use
 * it to spot mass deletion). It never changes what a delete does: a throwing
 * listener is swallowed.
 */
export function setSoftDeleteListener(listener: ((event: SoftDeleteEvent) => void) | null): void {
  softDeleteListener = listener;
}

function notifySoftDelete(model: string, count: number): void {
  if (!softDeleteListener || count <= 0) return;
  try {
    softDeleteListener({ model, count });
  } catch {
    // Observers must never break a delete.
  }
}

/**
 * How many rows matching `where` are still live, i.e. how many a delete is
 * about to soft-delete for the first time (a repeat delete only re-stamps
 * `deletedAt`). Only asked while a listener is registered. Read-only and
 * never throws: on failure it returns null and the caller falls back to the
 * write's own count.
 */
async function liveCount(delegate: any, where: any): Promise<number | null> {
  if (!softDeleteListener) return null;
  try {
    const n = await delegate.count({ where: { AND: [where ?? {}, { deletedAt: null }] } });
    return typeof n === 'number' ? n : null;
  } catch {
    return null;
  }
}

/** Same as {@link liveCount} for a single-row delete by unique `where`. */
async function liveOne(delegate: any, where: any): Promise<number | null> {
  if (!softDeleteListener) return null;
  try {
    const row = await delegate.findUnique({ where, select: { deletedAt: true } });
    return row ? (row.deletedAt === null ? 1 : 0) : null;
  } catch {
    return null;
  }
}

/**
 * Wraps a PrismaClient with the soft-delete extension.
 *
 * - find(Many|First|Unique[OrThrow]) / count / aggregate / groupBy on
 *   soft-delete models inject `where: { deletedAt: null }` automatically.
 * - delete / deleteMany on soft-delete models become an update setting
 *   `deletedAt = now()`.
 * - Pass `{ includeDeleted: true }` alongside query args to skip both filters.
 * - For genuine deletion (GDPR, seeds), call `model.hardDelete(...)` or
 *   `model.hardDeleteMany(...)`.
 *
 * Soft-delete models: User, Organization, Workspace, Project, Task, Lead,
 * Client, Document, FileObject, Comment, Contract, Expense, Invoice,
 * SignatureRequest.
 */
export function withSoftDelete(prisma: PrismaClient) {
  return prisma.$extends({
    name: 'softDelete',
    query: {
      $allModels: {
        async findMany({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          return query(includeDeleted ? rest : withDeletedAtNull(rest));
        },
        async findFirst({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          return query(includeDeleted ? rest : withDeletedAtNull(rest));
        },
        async findFirstOrThrow({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          return query(includeDeleted ? rest : withDeletedAtNull(rest));
        },
        async findUnique({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          if (includeDeleted) return query(rest);
          // findUnique can't filter by non-unique deletedAt; post-filter instead.
          const result = (await query(rest)) as { deletedAt?: Date | null } | null;
          return result && result.deletedAt ? null : result;
        },
        async findUniqueOrThrow({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          if (includeDeleted) return query(rest);
          const result = (await query(rest)) as { deletedAt?: Date | null } | null;
          if (result && result.deletedAt) {
            throw new Prisma.PrismaClientKnownRequestError('No record found', {
              code: 'P2025',
              clientVersion: Prisma.prismaVersion.client,
            });
          }
          return result;
        },
        async count({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          return query(includeDeleted ? rest : withDeletedAtNull(rest));
        },
        async aggregate({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          return query(includeDeleted ? rest : withDeletedAtNull(rest));
        },
        async groupBy({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const { rest, includeDeleted } = partition(args);
          return query(includeDeleted ? rest : withDeletedAtNull(rest));
        },
        async delete({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          // Convert delete -> update setting deletedAt. Routed through the raw
          // closed-over `prisma` so the extension's query interceptor doesn't
          // recurse on the inner update.
          const delegate = (prisma as any)[lcfirst(model as string)];
          const a: any = args;
          // Observation only: the write below is unchanged.
          const fresh = await liveOne(delegate, a.where);
          const deleted = await delegate.update({
            where: a.where,
            data: { deletedAt: new Date() },
            ...(a.select ? { select: a.select } : {}),
            ...(a.include ? { include: a.include } : {}),
          });
          notifySoftDelete(model as string, fresh ?? 1);
          return deleted;
        },
        async deleteMany({ model, args, query }) {
          if (!isSoftDeleteModel(model)) return query(args);
          const delegate = (prisma as any)[lcfirst(model as string)];
          const a: any = args;
          // Observation only: the write below is unchanged.
          const fresh = await liveCount(delegate, a.where);
          const result = await delegate.updateMany({
            where: a.where,
            data: { deletedAt: new Date() },
          });
          const hit = typeof result?.count === 'number' ? result.count : 0;
          notifySoftDelete(model as string, fresh === null ? hit : Math.min(fresh, hit));
          return result;
        },
      },
    },
    model: {
      $allModels: {
        /** Permanently delete a row, bypassing the soft-delete extension. */
        async hardDelete<M>(this: M, args: unknown): Promise<unknown> {
          const ctx = Prisma.getExtensionContext(this) as { $name: string };
          return (prisma as any)[lcfirst(ctx.$name)].delete(args);
        },
        /** Permanently delete many rows, bypassing the soft-delete extension. */
        async hardDeleteMany<M>(this: M, args: unknown): Promise<unknown> {
          const ctx = Prisma.getExtensionContext(this) as { $name: string };
          return (prisma as any)[lcfirst(ctx.$name)].deleteMany(args);
        },
      },
    },
  });
}

type SoftDeletedPrismaClient = ReturnType<typeof withSoftDelete>;
